import{z as l,x as A,o,c as p,q as t,j as d,D as e,d as r,s as i,S as s,b as n}from"./chunks/framework.C8m1ZpeB.js";const C=JSON.parse('{"title":"按秩与路径压缩","description":"","frontmatter":{"title":"按秩与路径压缩","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/uf-rank-compress.md","filePath":"cs/uf-rank-compress.md","lastUpdated":1791413859000}'),B={name:"cs/uf-rank-compress.md"};function c(m,a,f,h,u,D){const E=A("Mermaid");return o(),p("div",null,[a[2]||(a[2]=t('<h1 id="按秩与路径压缩" tabindex="-1">按秩与路径压缩 <a class="header-anchor" href="#按秩与路径压缩" aria-label="Permalink to &quot;按秩与路径压缩&quot;">​</a></h1><div class="epigraph"><p>矮树挂到高树上，高度有对数顶；再把路上的点直接接到根，摊还才掉到反 Ackermann。</p><footer>—— 据 Tarjan, Efficiency of a Good But Not Linear Set Union Algorithm, JACM 1975；Cormen, Leiserson, Rivest and Stein 第 21 章 整理</footer></div><p><a href="/cs/union-find">上一课</a>已经给出父指针森林、<code>find</code>/<code>union</code>，并点名按秩加压缩、摊还 \\(\\alpha(n)\\)，却把两条技术的不变式捆在一起。本课不重讲分区 ADT。缺口是把它们拆开：只按秩（或按大小）时高度 \\(O(\\log n)\\)；只压缩时最坏仍可差；合在一起秩是高度上界且压缩不增加秩。图表示下一课要存边，本课仍不存边。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>朴素 union 把一棵树挂到另一棵根上，链长可以 \\(\\Theta(n)\\)。按秩：根存一个整数 \\(\\mathrm{rank}\\)，union 时秩小的根挂到秩大的；仅当两秩相等时赢家秩加一。不变式：\\(\\mathrm{rank}[x]\\) 不小于子树高度的一个上界，且沿父严格降。缺口是证明<strong>秩一旦写出，压缩不得把秩改大</strong>，否则上界烂掉。</p><p>路径压缩：<code>find</code> 把沿途节点的父改成根（两趟或递归返回时改）。深度变 1，但秩字段保持原值——它不再等于真实高度，只是上界。</p><p><span class="marginnote">「秩」不是树的真实高度，而是一个只增不减的高度上界标记。路径压缩把树压扁后，真实高度变小了，秩保持原值继续当上界用——这正是它能当不变式的原因。</span></p><p><span class="marginnote">只压缩不按秩，Tarjan 仍给出摊还界，但实现上两条都做几乎零成本。主干两者都开。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><code>Link(x,y)</code> 两根：若 <code>rank[x]&lt;rank[y]</code> 则 <code>parent[x]=y</code>；对称；相等则 <code>parent[y]=x</code>，<code>rank[x]++</code>。<code>Find</code> 压缩不改 <code>rank</code>。按大小合并把 <code>rank</code> 换成子树规模，挂小到大，无压缩时高度 \\(O(\\log n)\\) 同样成立。</p>',10)),(o(),d(s,null,{default:e(()=>[i(E,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20U%5B%22%E4%B8%A4%E6%A0%B9%22%5D%20--%3E%20CMP%5B%22%E6%AF%94%E7%A7%A9%22%5D%0A%20%20CMP%20--%3E%20HANG%5B%22%E7%9F%AE%E6%8C%82%E9%AB%98%22%5D%0A%20%20F%5B%22find%20%E8%B7%AF%E5%BE%84%22%5D%20--%3E%20CMPR%5B%22%E6%B2%BF%E9%80%94%E7%88%B6%20%E2%86%90%20%E6%A0%B9%22%5D%0A%20%20CMPR%20--%3E%20RANK%5B%22%E7%A7%A9%E5%AD%97%E6%AE%B5%E4%B8%8D%E5%8A%A8%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=n("p",null,"调用方仍不得缓存旧根：压缩和 union 都会改代表。",-1)),a[4]||(a[4]=n("h2",{id:"机制",tabindex:"-1"},[r("机制 "),n("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=n("p",null,"秩在什么情况下才会变大——只有一种情形，其余全部不动：",-1)),(o(),d(s,null,{default:e(()=>[i(E,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20LINK%5B%22Link%20%E4%B8%A4%E6%A3%B5%E6%A0%91%E7%9A%84%E6%A0%B9%22%5D%20--%3E%20Q%7B%22%E4%B8%A4%E7%A7%A9%E7%9B%B8%E7%AD%89%EF%BC%9F%22%7D%0A%20%20Q%20--%3E%7C%22%E7%9B%B8%E7%AD%89%22%7C%20UP%5B%22%E8%B5%A2%E5%AE%B6%E7%A7%A9%E5%8A%A0%E4%B8%80%22%5D%0A%20%20Q%20--%3E%7C%22%E4%B8%8D%E7%AD%89%22%7C%20HANG%5B%22%E7%9F%AE%E6%A0%B9%E6%8C%82%E5%88%B0%E9%AB%98%E6%A0%B9%EF%BC%8C%E7%A7%A9%E4%B8%8D%E5%8F%98%22%5D%0A%20%20FIND%5B%22find%20%E6%B2%BF%E9%80%94%E5%8E%8B%E7%BC%A9%E7%88%B6%E6%8C%87%E9%92%88%22%5D%20--%3E%20KEEP%5B%22%E7%A7%A9%E5%AD%97%E6%AE%B5%E5%8E%9F%E6%A0%B7%E4%BF%9D%E7%95%99%22%5D%0A%20%20UP%20--%3E%20BOUND%5B%22%E7%A7%A9%20k%20%E7%9A%84%E6%A0%91%E8%87%B3%E5%B0%91%202%5Ek%20%E4%B8%AA%E8%8A%82%E7%82%B9%22%5D%0A%20%20HANG%20--%3E%20BOUND%0A%20%20KEEP%20--%3E%20BOUND%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=t('<p>有了秩上界，一棵秩为 \\(k\\) 的树至少 \\(2^k\\) 个节点（归纳：秩加一发生在两棵同秩树合并）。故最大秩 \\(O(\\log n)\\)，无压缩时 <code>find</code> 为 \\(O(\\log n)\\)。压缩把已经付过的路径摊到以后的 <code>find</code>。\\(\\alpha(n)\\) 本课仍不展开定义：合同写成「摊还几乎常数，单次最坏可较长」。</p><p><span class="marginnote">数字实例：两棵秩 2 的树合并才产生秩 3；由于秩 \\(k\\) 的树至少 \\(2^k\\) 个节点，\\(n=100\\) 万时最大秩约 19（\\(2^{19}\\approx52\\) 万）——不做压缩，<code>find</code> 也至多爬约 19 层。</span></p><p>与动态数组摊还不同：这里势能跟节点到根的距离、秩有关，Tarjan 的会计更细。邻接表课不需要这个势能。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入可持久化、不支持删边。也不把 \\(\\alpha(n)\\) 写成最坏 \\(O(1)\\)。图若还要枚举边，并查集不够——下一课邻接表与矩阵。</p><p>后课默认：实现并查集时按秩（或按大小）加压缩都打开。要存边集，换图表示。</p><p><span class="marginnote">常见误区：初学者容易以为路径压缩会把秩跟着降下来甚至清零。实际上压缩只是让秩「不再等于真实高度」，字段原样保留——一旦把秩当真实高度去维护，摊还上界就没了。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>按秩给出高度 \\(O(\\log n)\\) 上界；压缩不改秩字段。</li><li>合在一起摊还 \\(\\alpha(n)\\)；代表仍会变。</li><li>边的布局是下一课邻接表与矩阵。</li><li>出处：Tarjan, <em>JACM</em>, 1975；Cormen et al. 第 21 章。</li></ul>',9))])}const _=l(B,[["render",c]]);export{C as __pageData,_ as default};
